        }

        const wxImage mask = mask_bmp.ConvertToImage(), paint = paint_bmp.ConvertToImage();
        auto inside = [&](int x,int y) {
            return x >= 0 && y >= 0 && x < size && y < size && mask.GetRed(x,y) > 127;
        };
        auto is_border = [&](int x,int y) {
            return x >= 0 && y >= 0 && x < size && y < size && paint.GetRed(x,y) < 127;
        };

