    //
    // Rows are children of the popup, so they paint after it. A row that
    // reaches the popup's own edge covers the border stroke for its whole
    // height, in its own resting colour -- which for a menu row is the same
    // surface the popup is filled with, so the outline simply disappears
    // wherever a row sits. Returns the percentage of the border's side ink
    // that survives one row.
    static int side_border_surviving(int size, double radius, double row_inset)
    {
        const wxColour surface(255,255,255), border(0,0,0);
        wxBitmap bmp(size,size);
        wxMemoryDC dc(bmp);
        dc.SetBackground(wxBrush(surface)); dc.Clear();
        // The popup's own paint.
        dc.SetPen(wxPen(border)); dc.SetBrush(wxBrush(surface));
        dc.DrawRoundedRectangle(wxRect(0,0,size,size).Deflate(1),radius);

        auto side_ink = [&] {
            const wxImage image = bmp.ConvertToImage();
            double ink = 0.;
            // Down the sides only, clear of the rounded corners.
            for (int y = int(radius) + 2; y < size - int(radius) - 2; ++y)
                for (int x = 0; x < size; ++x)
                    if (x < 4 || x >= size - 4) ink += 255. - image.GetRed(x,y);
            return ink;
        };
        const double before = side_ink();

        // One row, painted on top the way a child does.
        {
            std::unique_ptr<wxGraphicsContext> gc(wxGraphicsContext::Create(dc));
            gc->SetPen(*wxTRANSPARENT_PEN);
            gc->SetBrush(wxBrush(surface));
            gc->DrawRectangle(row_inset,radius + 2,size - 2 * row_inset,size - 2 * radius - 4);
        }
        const double after = side_ink();
        return before <= 0. ? -1 : int(std::lround(after / before * 100.));
    }

    // A row must not paint over the outline it sits inside.
    void verify_menu_rows_leave_the_border_alone()
